package io.github.ningpp.compat;

/** Replacement for System.Security.Authentication.InvalidCredentialException (generated by CSharpToJava converter). */
public class InvalidCredentialException extends AuthenticationException {
    public InvalidCredentialException() { super(); }
    public InvalidCredentialException(String message) { super(message); }
    public InvalidCredentialException(String message, Throwable cause) { super(message, cause); }
}
